#!/bin/bash
set -e
DIR=/opt/hermes-chat-agent
cd $DIR
cp -f $DIR/chat_agent.py $DIR/chat_agent_prev.bak 2>/dev/null || true
base64 -d > $DIR/chat_agent.py <<'B64EOF'

B64EOF
systemctl restart hermes-chat-agent
sleep 20
echo "=== STATUS ==="
systemctl is-active hermes-chat-agent
echo "=== LOG ==="
tail -n 8 /var/log/hermes-chat-agent.log
echo "=== ПРАВИЛА ВКЛЮЧЕНЫ ==="
grep -c "MAX_AGE_DAYS = 7" $DIR/chat_agent.py
echo "=== ГОТОВО ==="
